scripts.杀手死亡.txt:
// 所有敌人死亡

	Add($fight011, 1);
	If ($fight011 == 30) @finished; 
    Return;
	
@finished:
	StopMusic();
	PlayMusic("追缘.mp3");
	ClearEffect();
	Sleep(500);
	Watch("独孤剑", "张琳心", 0);
	Say("张琳心：战斗的时候你干吗老挡在我前面？", 23);
	Say("独孤剑：你是女孩子嘛。", 2);
	Say("张琳心：女孩子怎么啦？你……小瞧我？", 23);
	Say("独孤剑：不，你误会了……我只是想保护你。", 8);
	Say("张琳心：……", 22);
	SetNpcScript("张琳心", "张琳心对话.txt");
	Assign($Event, 220);
	SetMapTrap(1, "Trap01.txt");
	SetMapTrap(2, "Trap02.txt");
	SetMapTrap(3, "Trap03.txt");
	Return;

scripts.五色教杀手.txt:
// 遇到五色教杀手，对话后战斗

	PlayerGoto(5, 109);
	SetPlayerDir(5);
	Say("独孤剑：哼！又是你们，你们到底是什么人！？", 5);
	Say("红衣杀手：杀手！", 80);
	Say("独孤剑：你们来这里干什么？", 5);
	Say("红衣杀手：杀人！", 80);
	Say("张琳心：你们说话都是两个字吗？", 21);
	Say("红衣杀手：不错。", 80);
	SetNpcKind("张琳心", 1);
	NpcGoto("张琳心", 6, 108);
	SetNpcDir("张琳心", 5);
	Say("张琳心：那我也有两个字想对你说。", 21);
	Say("红衣杀手：什么？", 80);
	Say("张琳心：去死！", 21);
	SetNpcKind("张琳心", 3);
	
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("红衣杀手",1);
	SetNpcRelation("黑衣杀手",1);
	SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	
	SetMapTrap(1, "Trap01.txt");
	SetMapTrap(2, "Trap02.txt");
	SetMapTrap(3, "Trap03.txt");
	Assign($Event, 215);
	Return;

scripts.张琳心对话.txt:
// 张琳心同伴对话

	If ($Event == 220) @Event220;
	If ($Event == 230) @Event230;
	If ($Event == 240) @Event240;
	
	Return;

@Event220:
	Say("独孤剑：你有没有受伤？", 1);
	Say("张琳心：你一直挡在我前面，我哪有机会受伤呀？", 22);
	Say("张琳心：哎呀！瞧！你的胳膊上都流血了！痛不痛？", 25);
	Say("独孤剑：没事！这点小伤算什么！我们快到大厅去看看吧！", 2);
	Say("张琳心：嗯！", 21);
	Return;

@Event230:	
	Say("张琳心：武夷山这么大，不知道禁地在哪里？", 24);
	Say("独孤剑：听张兄说禁地的入口是北山的一个山洞，我们到北边找找吧。", 1);
	Return;
	
@Event240:
	If ($Talkmap011 == 0) @Talk0;
	If ($Talkmap011 == 1) @Talk1;
@Talk0:	
	Say("张琳心：想不到武夷派竟惨遭灭门之祸！", 24);
	Say("独孤剑：没想到五色教的手段这么毒辣！他们为什么要铲平武夷派？难道也是为了……血书？你父亲……", 9);
	Say("张琳心：不！我父亲和五色教绝对没有关系！你……你不要错怪他！", 26);
	Say("独孤剑：对不起，张姑娘，我只是觉得这一切实在太凑巧了……", 8);
	Say("张琳心：我们去临安城找我爹，把一切都问个一清二楚！", 28);
	Say("独孤剑：……", 1);
	Assign($Talkmap011, 1);
	Return;	
@Talk1:
	Say("张琳心：我们去临安城找我爹，把一切都问个一清二楚！", 28);
	Say("独孤剑：……", 1);
	Return;

